"""process.chunk: LPT balancing, chunk files generated by the command, active-chunk gate."""

from __future__ import annotations

import datetime as _dt
import json

import pytest

from kallimachos.config.schema import ProcessConfig
from kallimachos.interfaces import UsageError, WorkKind, WorkState
from kallimachos.paths import DataLayout
from kallimachos.process import chunk as chunk_mod
from kallimachos.process import status as status_mod
from tests.unit.conftest_pdf import (  # noqa: F401
    EID_A,
    EID_B,
    EID_C,
    FakeCatalog,
    fake_store,
    layout_fixture,
    make_entry,
)

NOW = _dt.datetime(2026, 10, 18, 9, 0, tzinfo=_dt.UTC)


def test_lpt_groups_balances_pages() -> None:
    items = [("a", 40), ("b", 30), ("c", 20), ("d", 10), ("e", 10), ("f", 5)]
    groups = chunk_mod.lpt_groups(items, 3)
    assert sorted(len(g) for g in groups) == [3, 3]
    totals = sorted(sum(dict(items)[e] for e in g) for g in groups)
    assert totals == [55, 60]  # 40+10+5 vs 30+20+10
    assert groups[0][0] == "a"  # longest first
    assert chunk_mod.lpt_groups([], 3) == []
    assert chunk_mod.lpt_groups([("x", 0)], 3) == [["x"]]
    assert [len(g) for g in chunk_mod.lpt_groups(items[:4], 3)] == [2, 2]
    with pytest.raises(UsageError):
        chunk_mod.lpt_groups(items, 0)


def _catalog() -> FakeCatalog:
    return FakeCatalog(
        [
            make_entry(EID_A, pages=10, path="A-Chan/01-Sub/a.pdf"),
            make_entry(EID_B, pages=30, path="A-Chan/01-Sub/b.pdf", year=2015),
            make_entry(EID_C, pages=400, path="A-Chan/02-Sub/c.pdf", kind=WorkKind.BOOK),
            make_entry("111111111111", pages=20, path="A-Chan/02-Sub/d.pdf"),
            make_entry("222222222222", pages=7, path="B-Other/01-Sub/e.pdf", channel="B"),
        ]
    )


def test_create_chunk_writes_files_and_skips_books(layout: DataLayout) -> None:
    cfg = ProcessConfig()
    chunk = chunk_mod.create_chunk(_catalog(), layout, cfg, channel="A", size=10, now=NOW)
    assert chunk.number == 1
    assert chunk.eids == [EID_B, EID_A, "111111111111"]  # folder, then year
    assert chunk.books == [EID_C]
    assert chunk.groups == [[EID_B, EID_A], ["111111111111"]]  # LPT within each sub-folder
    d = layout.chunks_dir / "1"
    listing = json.loads((d / "list.json").read_text(encoding="utf-8"))
    assert listing["chunk"] == 1 and listing["channel"] == "A" and listing["remaining"] == 0
    assert [w["eid"] for w in listing["works"]] == chunk.eids
    assert json.loads((d / "groups.json").read_text(encoding="utf-8")) == chunk.groups
    log = (d / "log.md").read_text(encoding="utf-8")
    assert log.startswith("# Chunk 1 (A)") and "## Log" in log
    assert chunk_mod.load_chunk(layout, 1) == chunk


def test_second_chunk_excludes_earlier_eids_and_respects_size(layout: DataLayout) -> None:
    cfg = ProcessConfig()
    first = chunk_mod.create_chunk(_catalog(), layout, cfg, channel="A", size=2, now=NOW)
    assert len(first.eids) == 2
    listing = json.loads((layout.chunks_dir / "1" / "list.json").read_text(encoding="utf-8"))
    assert listing["remaining"] == 1
    second = chunk_mod.create_chunk(_catalog(), layout, cfg, channel="A", size=5, now=NOW)
    assert second.number == 2
    assert second.eids == ["111111111111"]
    assert second.books == []  # the book was listed in chunk 1 already
    with pytest.raises(UsageError):
        chunk_mod.load_chunk(layout, 9)


def test_active_chunks_and_log_event(layout: DataLayout) -> None:
    cfg = ProcessConfig()
    chunk = chunk_mod.create_chunk(_catalog(), layout, cfg, channel="A", size=10, now=NOW)
    assert [c.number for c in chunk_mod.active_chunks(layout)] == [1]
    for eid in chunk.eids:
        status_mod.ensure_started(layout, eid, by="t")
        for state in (
            WorkState.TEXT_EXTRACTED,
            WorkState.CARD_WRITTEN,
            WorkState.CHECK_PASSED,
            WorkState.SEMANTIC_VERIFIED,
            WorkState.NOTE_WRITTEN,
        ):
            status_mod.record_state(layout, eid, state, by="t")
    assert chunk_mod.active_chunks(layout) == []
    touched = chunk_mod.log_event(layout, [EID_A], "check passed", now=NOW)
    assert touched == [layout.chunks_dir / "1" / "log.md"]
    log = touched[0].read_text(encoding="utf-8")
    assert log.rstrip().endswith(f"- {NOW.isoformat(timespec='seconds')} check passed")
    assert chunk_mod.log_event(layout, ["ffffffffffff"], "nothing") == []
    assert [c.number for c in chunk_mod.chunks_containing(layout, EID_C)] == [1]
